let DATA = null;
let currentSection = 'dashboard';

const $ = (s) => document.querySelector(s);
const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (c) => ({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;' }[c]));
const money = (n) => `₹${Number(n || 0).toLocaleString('en-IN')}`;
const AICONS = {
  home:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 10 8-7 8 7v10a1 1 0 0 1-1 1h-4v-6H9v6H5a1 1 0 0 1-1-1V10Z"/></svg>',
  products:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16v13H4zM7 7V5a5 5 0 0 1 10 0v2M9 12h6"/></svg>',
  designs:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 1.7 5.3L19 10l-5.3 1.7L12 17l-1.7-5.3L5 10l5.3-1.7L12 3ZM19 16l.6 1.9L22 18.5l-2.4.6L19 21l-.6-1.9-2.4-.6 2.4-.6L19 16Z"/></svg>',
  gallery:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.2"/><path d="m5 17 4-4 3 3 2-2 5 5"/></svg>',
  customers:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="9" r="3"/><circle cx="16.5" cy="10" r="2.4"/><path d="M3.5 19c.6-3 2.4-4.5 5.5-4.5S13.9 16 14.5 19M14 15.5c2.9-.7 5.5.9 6 3.5"/></svg>',
  reviews:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/></svg>',
  faq:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M9.8 9.2a2.5 2.5 0 1 1 4.1 1.9c-1.1.9-1.9 1.2-1.9 2.4M12 17h.01"/></svg>',
  offers:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7.5V4h3.5L20 16.5 16.5 20 4 7.5Z"/><path d="M8 8h.01"/></svg>',
  content:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19h4l10-10-4-4L5 15v4Z"/><path d="m13 6 4 4"/></svg>',
  settings:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="M3.5 13.2v-2.4l2-.7.7-1.7-1-1.9 1.7-1.7 1.9 1 .7-.3.9-2.1h2.4l.8 2.1.7.3 1.9-1 1.7 1.7-1 1.9.7 1.7 2 .7v2.4l-2 .7-.7 1.7 1 1.9-1.7 1.7-1.9-1-.7.3-.8 2.1h-2.4l-.9-2.1-.7-.3-1.9 1-1.7-1.7 1-1.9-.7-1.7-2-.7Z"/></svg>',
  stats:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19V9M12 19V5M19 19v-7"/></svg>',
  enquiries:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16v12H4z"/><path d="m4 14h4l1.3 2h5.4L16 14h4"/></svg>'
};
function aicon(name){return `<span class="admin-icon">${AICONS[name]||''}</span>`;}
const api = async (path, options = {}) => {
  const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || `Request failed (${response.status})`);
  return data;
};

function toast(message, error=false){
  document.querySelector('.toast')?.remove();
  const el=document.createElement('div');
  el.className=`toast ${error?'toast-error':''}`;
  el.setAttribute('role','status');
  el.textContent=message;
  document.body.appendChild(el);
  setTimeout(()=>el.remove(),3600);
}

function modal(title, body, actions=''){
  document.querySelector('.admin-modal')?.remove();
  const el=document.createElement('div');
  el.className='admin-modal';
  el.innerHTML=`<div class="modal-card"><div class="modal-head"><div><div class="eyebrow">MazaTowel Admin</div><h2>${esc(title)}</h2></div><button class="btn btn-secondary" onclick="closeGeneric()">Close</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;
  document.body.appendChild(el);
}
function closeGeneric(){ document.querySelector('.admin-modal')?.remove(); }
function reader(input, callback){
  const file=input?.files?.[0]; if(!file)return callback(null);
  if(!file.type.startsWith('image/'))return toast('Please select an image file.',true);
  if(file.size>8*1024*1024)return toast('Image is too large. Please keep it below 8 MB.',true);
  const r=new FileReader(); r.onload=()=>callback({dataUrl:r.result,name:file.name,size:file.size}); r.onerror=()=>toast('Could not read the image file.',true); r.readAsDataURL(file);
}
function escJson(value){return esc(JSON.stringify(value??''));}
async function refreshData(){ try{ DATA=await api('/api/admin-data'); renderAllSections(); showSection(currentSection); toast('Latest website data loaded.'); }catch(e){toast(e.message,true);} }
async function load(){ DATA=await api('/api/admin-data'); renderShell(); showSection('dashboard'); }

function renderShell(){
  const menu=[['dashboard','home','Dashboard'],['products','products','Products'],['designs','designs','Design Library'],['gallery','gallery','Gallery'],['customers','customers','Our Customers'],['reviews','reviews','Reviews'],['enquiries','enquiries','Enquiries'],['faq','faq','FAQ'],['offers','offers','Offers'],['content','content','Homepage'],['settings','settings','Settings'],['stats','stats','Business Counts']];
  const mobile=['dashboard','products','designs','enquiries','reviews'];
  $('#adminApp').innerHTML=`<div class="admin-shell"><aside class="sidebar"><div class="brand"><img class="brand-logo" src="/assets/mazatowel-logo-tight.png" alt="MazaTowel logo"></div><div class="admin-menu">${menu.map(x=>`<button data-section="${x[0]}" onclick="showSection('${x[0]}',this)">${aicon(x[1])}<b>${x[2]}</b></button>`).join('')}</div><div class="side-bottom"><button onclick="downloadBackup()">Export Backup</button><button onclick="$('#importBackup').click()">Import Backup</button><input id="importBackup" type="file" accept="application/json" hidden onchange="importBackupFile(this)"><button onclick="window.open('/','_blank','noopener')">View Website</button><button onclick="logout()">Logout</button></div></aside><main class="main"><div class="topbar"><div><h1 id="pageTitle">Dashboard</h1><p>Manage products, designs, photos, customers, reviews and business content.</p></div><div class="toolbar"><button class="btn btn-secondary" onclick="refreshData()">↻ Refresh</button><button class="btn btn-primary" onclick="quickAdd()">+ Quick Add</button></div></div><div class="content">${['dashboard','products','designs','gallery','customers','reviews','enquiries','faq','offers','content','settings','stats'].map(s=>`<section id="sec-${s}" class="admin-section"></section>`).join('')}</div><div class="mobile-admin-bar">${mobile.map(x=>`<button data-mobile="${x}" onclick="showSection('${x}')">${x==='dashboard'?'Home':x==='designs'?'Designs':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></main></div>`;
  renderAllSections();
}
function showSection(id,el){ currentSection=id; document.querySelectorAll('.admin-section').forEach(x=>x.classList.remove('active')); $('#sec-'+id)?.classList.add('active'); document.querySelectorAll('.admin-menu button').forEach(x=>x.classList.toggle('active',x.dataset.section===id)); document.querySelectorAll('[data-mobile]').forEach(x=>x.classList.toggle('active',x.dataset.mobile===id)); const labels={dashboard:'Dashboard',products:'Products',designs:'Design Library',gallery:'Gallery',customers:'Our Customers',reviews:'Reviews',enquiries:'Customer Enquiries',faq:'FAQ',offers:'Offers',content:'Homepage Content',settings:'Settings',stats:'Business Counts'}; $('#pageTitle').textContent=labels[id]||id; renderSection(id); }
function renderAllSections(){ ['dashboard','products','designs','gallery','customers','reviews','enquiries','faq','offers','content','settings','stats'].forEach(renderSection); }
function renderSection(id){ const el=$('#sec-'+id); if(!el)return; const map={dashboard:renderDashboard,products:renderProducts,designs:renderDesigns,gallery:renderGallery,customers:renderCustomers,reviews:renderReviews,enquiries:renderEnquiries,faq:renderFaq,offers:renderOffers,content:renderContent,settings:renderSettings,stats:renderStats}; el.innerHTML=map[id](); }

function renderDashboard(){
  const pending=DATA.reviews.filter(r=>!r.published).length; const newEnquiries=(DATA.enquiries||[]).filter(e=>e.status==='New').length;
  return `<div class="cards"><div class="stat-card"><div class="label">Products</div><div class="num">${DATA.products.length}</div></div><div class="stat-card"><div class="label">Designs</div><div class="num">${DATA.designs.length}</div></div><div class="stat-card"><div class="label">Corporate Customers</div><div class="num">${DATA.customers.length}</div></div><div class="stat-card"><div class="label">Published Reviews</div><div class="num">${DATA.reviews.filter(r=>r.published).length}</div></div><div class="stat-card"><div class="label">Pending Reviews</div><div class="num">${pending}</div></div><div class="stat-card"><div class="label">New Enquiries</div><div class="num">${newEnquiries}</div></div><div class="stat-card"><div class="label">Gallery Photos</div><div class="num">${DATA.gallery.length}</div></div><div class="stat-card"><div class="label">Towels Sold</div><div class="num">${Number(DATA.stats.towelsSold||0).toLocaleString('en-IN')}</div></div><div class="stat-card"><div class="label">Designs Made</div><div class="num">${Number(DATA.stats.designsMade||0).toLocaleString('en-IN')}</div></div></div><div class="panel"><div class="panel-head"><h2>Quick actions</h2></div><div class="panel-body"><div class="toolbar"><button class="btn btn-primary" onclick="openProductForm()">+ Add Product</button><button class="btn btn-gold" onclick="openDesignForm()">+ Upload Design</button><button class="btn btn-secondary" onclick="showSection('gallery')">+ Upload Photos</button><button class="btn btn-secondary" onclick="openCustomerForm()">+ Add Customer</button><button class="btn btn-secondary" onclick="openReviewForm()">+ Add Review</button><button class="btn btn-secondary" onclick="showSection('enquiries')">View Enquiries</button><button class="btn btn-secondary" onclick="showSection('stats')">Update Counts</button></div></div></div><div class="panel"><div class="panel-head"><h2>Website health</h2><button class="btn btn-secondary" onclick="checkSiteHealth()">Check Now</button></div><div class="panel-body"><div class="muted">Use this check after publishing updates. It verifies the public API and site data are reachable.</div><div id="healthResult" style="margin-top:12px"></div></div></div>`;
}
async function checkSiteHealth(){ try{const d=await api('/api/health');$('#healthResult').innerHTML=`<div class="health-ok">✓ Website API is healthy. Last checked ${new Date(d.time).toLocaleString('en-IN')}.</div>`;toast('Website health check passed.');}catch(e){$('#healthResult').innerHTML=`<div class="health-error">✕ ${esc(e.message)}</div>`;toast(e.message,true);}}

function renderProducts(){
  return `<div class="panel"><div class="panel-head"><h2>Products</h2><button class="btn btn-primary" onclick="openProductForm()">+ Add Product</button></div><div class="panel-body"><input class="table-search" id="productSearchAdmin" oninput="filterRows('productTable','productSearchAdmin')" placeholder="Search products…"><div class="table-wrap"><table id="productTable"><thead><tr><th>Image</th><th>Product</th><th>Category</th><th>Size</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody>${DATA.products.map(p=>`<tr><td><div class="thumb"><img src="${esc(p.image||'')}" onerror="this.src='${placeholderAdmin(p.name)}'"></div></td><td><strong>${esc(p.name)}</strong><div class="muted">${esc(p.slug||'')}</div></td><td>${esc(p.category)}</td><td>${esc(p.size)}</td><td>${money(p.price)}</td><td><span class="status ${p.published!==false?'live':'off'}">${p.published!==false?'Published':'Hidden'}</span></td><td><div class="toolbar"><button class="btn btn-secondary" onclick="openProductForm('${p.id}')">Edit</button><button class="btn ${p.published!==false?'btn-gold':'btn-success'}" onclick="togglePublish('products','${p.id}')">${p.published!==false?'Hide':'Publish'}</button><button class="btn btn-danger" onclick="deleteItem('products','${p.id}')">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="7"><div class="empty">No products yet.</div></td></tr>`}</tbody></table></div></div></div>`;
}
function renderDesigns(){ return `<div class="panel"><div class="panel-head"><h2>Design Library</h2><button class="btn btn-primary" onclick="openDesignForm()">+ Add Design</button></div><div class="panel-body"><input class="table-search" id="designSearchAdmin" oninput="filterRows('designTable','designSearchAdmin')" placeholder="Search designs…"><div class="table-wrap"><table id="designTable"><thead><tr><th>Image</th><th>Design ID</th><th>Name</th><th>Category</th><th>Status</th><th>Actions</th></tr></thead><tbody>${DATA.designs.map(d=>`<tr><td><div class="thumb"><img src="${esc(d.image||'')}" onerror="this.src='${placeholderAdmin(d.name)}'"></div></td><td><strong>${esc(d.designId||'')}</strong></td><td>${esc(d.name)}</td><td>${esc(d.category)}</td><td><span class="status ${d.published!==false?'live':'off'}">${d.published!==false?'Published':'Hidden'}</span></td><td><div class="toolbar"><button class="btn btn-secondary" onclick="openDesignForm('${d.id}')">Edit</button><button class="btn ${d.published!==false?'btn-gold':'btn-success'}" onclick="togglePublish('designs','${d.id}')">${d.published!==false?'Hide':'Publish'}</button><button class="btn btn-danger" onclick="deleteItem('designs','${d.id}')">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">No designs yet.</div></td></tr>`}</tbody></table></div></div></div>`; }
function renderGallery(){ return `<div class="panel"><div class="panel-head"><h2>Gallery Photos</h2><div><input id="galleryUpload" type="file" accept="image/*" multiple hidden onchange="uploadGallery(this)"><button class="btn btn-primary" onclick="$('#galleryUpload').click()">+ Upload Photos</button></div></div><div class="panel-body"><p class="muted">Uploaded images are stored in <code>public/uploads/gallery/</code>.</p><div class="admin-gallery-grid">${DATA.gallery.map(g=>`<div class="gallery-admin-card"><img src="${esc(g.image)}" alt="${esc(g.alt||'MazaTowel photo')}"><div><strong>${esc(g.alt||'MazaTowel photo')}</strong><div class="toolbar"><button class="btn btn-secondary" onclick="editGallery('${g.id}')">Edit</button><button class="btn btn-danger" onclick="deleteItem('gallery','${g.id}')">Delete</button></div></div></div>`).join('')||`<div class="empty">No gallery photos yet. Upload your real work here.</div>`}</div></div></div>`; }
function renderCustomers(){ return `<div class="panel"><div class="panel-head"><h2>Our Corporate Customers</h2><button class="btn btn-primary" onclick="openCustomerForm()">+ Add Customer</button></div><div class="panel-body"><p class="muted">Add customer names, logos and optional websites. Published entries appear in the public “Our Customers” section.</p><div class="customer-admin-grid">${DATA.customers.map(c=>`<article class="customer-admin-card"><div class="customer-admin-logo">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}">`:`<span>${esc(c.name).slice(0,2).toUpperCase()}</span>`}</div><strong>${esc(c.name)}</strong>${c.tagline?`<p>${esc(c.tagline)}</p>`:''}<span class="status ${c.published!==false?'live':'off'}">${c.published!==false?'Published':'Hidden'}</span><div class="toolbar"><button class="btn btn-secondary" onclick="openCustomerForm('${c.id}')">Edit</button><button class="btn ${c.published!==false?'btn-gold':'btn-success'}" onclick="togglePublish('customers','${c.id}')">${c.published!==false?'Hide':'Publish'}</button><button class="btn btn-danger" onclick="deleteItem('customers','${c.id}')">Delete</button></div></article>`).join('')||`<div class="empty">No corporate customers added yet.</div>`}</div></div></div>`; }
function renderReviews(){ const pending=DATA.reviews.filter(r=>!r.published).length; const newEnquiries=(DATA.enquiries||[]).filter(e=>e.status==='New').length; return `<div class="panel"><div class="panel-head"><h2>Reviews</h2><div class="toolbar"><button class="btn btn-primary" onclick="openReviewForm()">+ Add Manual Review</button><button class="btn btn-secondary" onclick="openGoogleSettings()">Google Settings</button><button class="btn btn-gold" onclick="testGoogleReviews()">Check Google</button><button class="btn btn-secondary" onclick="$('#googleImport').click()">Import Google JSON</button><input id="googleImport" type="file" accept="application/json" hidden onchange="importGoogleReviews(this)"></div></div><div class="panel-body"><div class="notice">${pending?`You have <strong>${pending}</strong> review(s) waiting for moderation.`:'All current reviews are moderated.'} Live Google Reviews can be displayed automatically after Google Places API is configured.</div><div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>Customer</th><th>Source</th><th>Rating</th><th>Review</th><th>Status</th><th>Actions</th></tr></thead><tbody>${DATA.reviews.map(r=>`<tr><td><strong>${esc(r.name)}</strong><div class="muted">${esc(r.date||'')}</div></td><td>${esc(r.source||'Manual')}</td><td>${'★'.repeat(Math.max(0,Math.min(5,Number(r.rating)||0)))}</td><td><div class="review-admin-text">${esc(r.text)}</div></td><td><span class="status ${r.published?'live':'pending'}">${r.published?'Published':'Pending'}</span>${r.featured?` <span class="status live">Featured</span>`:''}</td><td><div class="toolbar"><button class="btn btn-secondary" onclick="openReviewForm('${r.id}')">Edit</button><button class="btn btn-gold" onclick="toggleReview('${r.id}')">${r.published?'Hide':'Publish'}</button><button class="btn btn-secondary" onclick="featureReview('${r.id}')">${r.featured?'Unfeature':'Feature'}</button><button class="btn btn-danger" onclick="deleteItem('reviews','${r.id}')">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">No reviews yet.</div></td></tr>`}</tbody></table></div></div></div>`; }
function renderEnquiries(){ const list=DATA.enquiries||[]; return `<div class="panel"><div class="panel-head"><h2>Customer Enquiries</h2><span class="status live">${list.filter(e=>e.status==='New').length} New</span></div><div class="panel-body"><p class="muted">Requests submitted from the website without requiring WhatsApp login. Use the customer number to call or message them from your own business phone.</p><div class="table-wrap"><table id="enquiryTable"><thead><tr><th>Customer</th><th>Product</th><th>Customization</th><th>Contact</th><th>Status</th><th>Actions</th></tr></thead><tbody>${list.map(e=>`<tr><td><strong>${esc(e.customerName)}</strong><div class="muted">${esc(new Date(e.createdAt).toLocaleString('en-IN'))}</div></td><td>${esc(e.product)}<div class="muted">${esc(e.size)} × ${esc(e.quantity)}</div></td><td><div><strong>${esc(e.embroideryName)}</strong></div><div class="muted">${esc(e.thread)}${e.design?` • ${esc(e.design)}`:''}</div>${e.notes?`<div class="review-admin-text">${esc(e.notes)}</div>`:''}</td><td><a class="admin-phone-link" href="tel:+${esc(e.phone)}">+${esc(e.phone)}</a></td><td><span class="status ${e.status==='Closed'?'off':e.status==='In Progress'?'live':'pending'}">${esc(e.status||'New')}</span></td><td><div class="toolbar"><button class="btn btn-secondary" onclick="setEnquiryStatus('${e.id}','In Progress')">In Progress</button><button class="btn btn-success" onclick="setEnquiryStatus('${e.id}','Closed')">Close</button><a class="btn btn-gold" target="_blank" rel="noopener" href="https://wa.me/${esc(e.phone)}?text=${encodeURIComponent('Hello '+(DATA.settings?.brand||'MazaTowel')+'! Thank you for your enquiry about '+e.product+'. We are following up regarding your customization request.') }">WhatsApp</a><button class="btn btn-danger" onclick="deleteItem('enquiries','${e.id}')">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="6"><div class="empty"><strong>No customer enquiries yet.</strong><div>Website requests will appear here when a customer submits the customization form.</div></div></td></tr>`}</tbody></table></div></div></div>`; }
function renderFaq(){ return `<div class="panel"><div class="panel-head"><h2>FAQ</h2><button class="btn btn-primary" onclick="openFaqForm()">+ Add FAQ</button></div><div class="panel-body"><div class="list-stack">${DATA.faqs.map(f=>`<div class="list-row"><div><strong>${esc(f.q)}</strong><p>${esc(f.a)}</p></div><div class="toolbar"><span class="status ${f.published?'live':'off'}">${f.published?'Published':'Hidden'}</span><button class="btn btn-secondary" onclick="openFaqForm('${f.id}')">Edit</button><button class="btn btn-gold" onclick="togglePublish('faqs','${f.id}')">${f.published?'Hide':'Publish'}</button><button class="btn btn-danger" onclick="deleteItem('faqs','${f.id}')">Delete</button></div></div>`).join('')||`<div class="empty">No FAQs yet.</div>`}</div></div></div>`; }
function renderOffers(){ return `<div class="panel"><div class="panel-head"><h2>Offers</h2><button class="btn btn-primary" onclick="openOfferForm()">+ Add Offer</button></div><div class="panel-body"><div class="list-stack">${DATA.offers.map(o=>`<div class="list-row"><div><strong>${esc(o.title)}</strong><p>${esc(o.description||'')}</p><span class="muted">${esc(o.startDate||'')} → ${esc(o.endDate||'')}</span></div><div class="toolbar"><span class="status ${o.active?'live':'off'}">${o.active?'Active':'Inactive'}</span><button class="btn btn-secondary" onclick="openOfferForm('${o.id}')">Edit</button><button class="btn btn-gold" onclick="toggleOffer('${o.id}')">${o.active?'Disable':'Enable'}</button><button class="btn btn-danger" onclick="deleteItem('offers','${o.id}')">Delete</button></div></div>`).join('')||`<div class="empty">No offers added yet.</div>`}</div></div></div>`; }
function renderContent(){ const c=DATA.content||{}; const lines=(arr=[])=>arr.map(x=>`${x.title} || ${x.text}`).join('\n'); return `<div class="panel"><div class="panel-head"><h2>Homepage & education content</h2><button class="btn btn-primary" onclick="saveContent()">Save Changes</button></div><div class="panel-body"><div class="form-grid"><div class="field"><label>Hero badge</label><input id="cHeroBadge" value="${esc(c.heroBadge)}"></div><div class="field"><label>Hero heading</label><input id="cHeroHeading" value="${esc(c.heroHeading)}"></div><div class="field span-2"><label>Hero text</label><textarea id="cHeroText">${esc(c.heroText)}</textarea></div><div class="field"><label>Why personalize title</label><input id="cWhyTitle" value="${esc(c.whyTitle)}"></div><div class="field"><label>Why personalize intro</label><textarea id="cWhyText">${esc(c.whyText)}</textarea></div><div class="field span-2"><label>Why points — one per line: Title || Text</label><textarea id="cWhyPoints">${esc(lines(c.whyPoints))}</textarea></div><div class="field"><label>Hygiene title</label><input id="cHygieneTitle" value="${esc(c.hygieneTitle)}"></div><div class="field"><label>Hygiene intro</label><textarea id="cHygieneText">${esc(c.hygieneText)}</textarea></div><div class="field span-2"><label>Hygiene points — one per line: Title || Text</label><textarea id="cHygienePoints">${esc(lines(c.hygienePoints))}</textarea></div><div class="field span-2"><label>Hygiene note</label><textarea id="cHygieneNote">${esc(c.hygieneNote)}</textarea></div><div class="field"><label>About title</label><input id="cAboutTitle" value="${esc(c.aboutTitle)}"></div><div class="field"><label>About text</label><textarea id="cAboutText">${esc(c.aboutText)}</textarea></div><div class="field"><label>Final CTA title</label><input id="cFinalTitle" value="${esc(c.finalTitle)}"></div><div class="field"><label>Final CTA text</label><textarea id="cFinalText">${esc(c.finalText)}</textarea></div></div></div></div>`; }
function renderSettings(){ const s=DATA.settings||{}; return `<div class="panel"><div class="panel-head"><h2>Business & WhatsApp Settings</h2><button class="btn btn-primary" onclick="saveSettings()">Save Settings</button></div><div class="panel-body"><div class="form-grid"><div class="field"><label>Brand name</label><input id="sBrand" value="${esc(s.brand)}"></div><div class="field"><label>Tagline</label><input id="sTagline" value="${esc(s.tagline)}"></div><div class="field"><label>WhatsApp number (international digits only)</label><input id="sWhatsApp" value="${esc(s.whatsapp)}"></div><div class="field"><label>Shipping charge</label><input id="sShipping" type="number" min="0" value="${Number(s.shipping||0)}"></div><div class="field"><label>Instagram URL</label><input id="sInstagram" value="${esc(s.instagram)}"></div><div class="field"><label>Facebook URL</label><input id="sFacebook" value="${esc(s.facebook)}"></div><div class="field"><label>Email</label><input id="sEmail" value="${esc(s.email)}"></div><div class="field"><label>Address</label><input id="sAddress" value="${esc(s.address)}"></div><div class="field span-2"><label>Payment terms</label><textarea id="sPayment">${esc(s.payment)}</textarea></div><div class="field"><label>COD</label><select id="sCod"><option value="false" ${!s.cod?'selected':''}>Not available</option><option value="true" ${s.cod?'selected':''}>Available</option></select></div><div class="field"><label>Established</label><input id="sEstablished" value="${esc(s.established)}"></div></div></div></div><div class="panel"><div class="panel-head"><h2>Google Reviews</h2><button class="btn btn-gold" onclick="testGoogleReviews()">Check Connection</button></div><div class="panel-body"><div class="field"><label>Google Place ID</label><input id="sGooglePlaceId" value="${esc(s.googlePlaceId||'')}" placeholder="Paste your Google Place ID"><div class="field-help">The API key is stored on the server in <code>.env</code>; do not put it here.</div></div><label class="check" style="margin-top:14px"><input id="sGoogleEnabled" type="checkbox" ${s.googleReviewsEnabled===true?'checked':''}> Show live Google reviews on the public website</label><div class="notice" style="margin-top:14px">After saving, use “Check Connection”. Live reviews will only be shown publicly when this switch is enabled and the server has a valid Google Places API key.</div><div id="googleStatusResult" style="margin-top:12px"></div><button class="btn btn-primary" style="margin-top:14px" onclick="saveGoogleSettings()">Save Google Review Settings</button></div></div>`; }
function renderStats(){ return `<div class="panel"><div class="panel-head"><h2>Business Counts</h2><button class="btn btn-primary" onclick="saveStats()">Save Counts</button></div><div class="panel-body"><div class="form-grid"><div class="field"><label>Towels Sold</label><input id="stTowels" type="number" min="0" value="${Number(DATA.stats.towelsSold||0)}"></div><div class="field"><label>Designs Made</label><input id="stDesigns" type="number" min="0" value="${Number(DATA.stats.designsMade||0)}"></div></div><div class="notice" style="margin-top:14px">Use verified figures only. These numbers appear as animated counters on the public website.</div></div></div>`; }

function placeholderAdmin(label){ return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><rect width="160" height="120" fill="#eaf7f6"/><text x="80" y="60" text-anchor="middle" dominant-baseline="middle" font-family="Arial" font-size="12" font-weight="700" fill="#2f7f82">${String(label||'MazaTowel').slice(0,18)}</text></svg>`)}`; }
function filterRows(tableId,inputId){ const q=($('#'+inputId).value||'').toLowerCase(); document.querySelectorAll('#'+tableId+' tbody tr').forEach(tr=>tr.style.display=tr.textContent.toLowerCase().includes(q)?'':'none'); }

function openProductForm(id){
  const p=id?DATA.products.find(x=>x.id===id):{name:'',category:'Bath Towels',size:'30 × 60 inch',price:399,desc:'',badge:'Personalized',image:'',published:true,featured:false,bestSeller:false};
  modal(`${id?'Edit':'Add'} Product`,`<div class="form-grid"><div class="field"><label>Product Name</label><input id="pName" value="${esc(p.name)}"></div><div class="field"><label>Category</label><select id="pCategory">${['Bath Towels','Face Towels','Hand Towels','Kids Towels','Family Towel Sets','Personalized Gifts','Custom Designs','Corporate Orders','Embroidered T-Shirts','Embroidered Caps','Embroidered Napkins'].map(x=>`<option ${x===p.category?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Size</label><input id="pSize" value="${esc(p.size)}"></div><div class="field"><label>Price</label><input id="pPrice" type="number" min="0" value="${Number(p.price||0)}"></div><div class="field"><label>Badge</label><input id="pBadge" value="${esc(p.badge||'Personalized')}"></div><div class="field span-2"><label>Description</label><textarea id="pDesc">${esc(p.desc)}</textarea></div><div class="field span-2"><label>Product photo</label><input id="pImage" type="file" accept="image/*"><div id="pPreview" class="upload-preview">${p.image?`<img src="${esc(p.image)}" alt="">`:'No new photo selected'}</div></div><label class="check"><input id="pPublished" type="checkbox" ${p.published!==false?'checked':''}> Published</label><label class="check"><input id="pFeatured" type="checkbox" ${p.featured?'checked':''}> Featured</label><label class="check"><input id="pBest" type="checkbox" ${p.bestSeller?'checked':''}> Best Seller</label></div>`,`<button class="btn btn-primary" onclick="saveProduct('${id||''}')">Save Product</button>`);
  $('#pImage').addEventListener('change',()=>previewFile($('#pImage'),$('#pPreview')));
}
function previewFile(input,preview){ reader(input,file=>{if(file)preview.innerHTML=`<img src="${file.dataUrl}" alt="Preview">`;}); }
async function saveProduct(id){ try{let imgData=null;if($('#pImage').files[0]) imgData=await fileToData($('#pImage'));const p={name:$('#pName').value.trim(),category:$('#pCategory').value,size:$('#pSize').value.trim(),price:Number($('#pPrice').value)||0,desc:$('#pDesc').value.trim(),badge:$('#pBadge').value.trim(),published:$('#pPublished').checked,featured:$('#pFeatured').checked,bestSeller:$('#pBest').checked};if(!p.name||!p.size)throw new Error('Product name and size are required.');if(imgData){p.imageData=imgData.dataUrl;p.imageName=imgData.name;}await saveCollection('products',id,p);closeGeneric();toast(id?'Product updated successfully.':'Product created successfully.');}catch(e){toast(e.message,true);} }

function openDesignForm(id){ const d=id?DATA.designs.find(x=>x.id===id):{designId:'',name:'',category:'Names & Initials',desc:'',image:'',published:true,featured:false}; modal(`${id?'Edit':'Add'} Design`,`<div class="form-grid"><div class="field"><label>Design ID</label><input id="dCode" value="${esc(d.designId)}" placeholder="MT-061"></div><div class="field"><label>Design Name</label><input id="dName" value="${esc(d.name)}"></div><div class="field"><label>Category</label><select id="dCategory">${['Names & Initials','Kids','Cartoons','Animals','Sports','Flowers','Traditional','Couples','Wedding','Birthday','Corporate','Photo Portrait Embroidery','Custom Artwork'].map(x=>`<option ${x===d.category?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span-2"><label>Description</label><textarea id="dDesc">${esc(d.desc)}</textarea></div><div class="field span-2"><label>Design image</label><input id="dImage" type="file" accept="image/*"><div id="dPreview" class="upload-preview">${d.image?`<img src="${esc(d.image)}" alt="">`:'No new image selected'}</div></div><label class="check"><input id="dPublished" type="checkbox" ${d.published!==false?'checked':''}> Published</label><label class="check"><input id="dFeatured" type="checkbox" ${d.featured?'checked':''}> Featured</label></div>`,`<button class="btn btn-primary" onclick="saveDesign('${id||''}')">Save Design</button>`); $('#dImage').addEventListener('change',()=>previewFile($('#dImage'),$('#dPreview'))); }
async function saveDesign(id){try{let image=null;if($('#dImage').files[0])image=await fileToData($('#dImage'));const d={designId:$('#dCode').value.trim()||`MT-${String(DATA.designs.length+1).padStart(3,'0')}`,name:$('#dName').value.trim(),category:$('#dCategory').value,desc:$('#dDesc').value.trim(),published:$('#dPublished').checked,featured:$('#dFeatured').checked};if(!d.name)throw new Error('Design name is required.');if(image){d.imageData=image.dataUrl;d.imageName=image.name;}await saveCollection('designs',id,d);closeGeneric();toast(id?'Design updated successfully.':'Design created successfully.');}catch(e){toast(e.message,true)}}

function openCustomerForm(id){ const c=id?DATA.customers.find(x=>x.id===id):{name:'',tagline:'',website:'',image:'',published:true}; modal(`${id?'Edit':'Add'} Corporate Customer`,`<div class="form-grid"><div class="field"><label>Customer / Company Name</label><input id="cuName" value="${esc(c.name)}"></div><div class="field"><label>Short description (optional)</label><input id="cuTagline" value="${esc(c.tagline||'')}"></div><div class="field span-2"><label>Website URL (optional)</label><input id="cuWebsite" value="${esc(c.website||'')}" placeholder="https://example.com"></div><div class="field span-2"><label>Customer logo</label><input id="cuImage" type="file" accept="image/*"><div id="cuPreview" class="upload-preview">${c.image?`<img src="${esc(c.image)}" alt="">`:'No logo selected'}</div></div><label class="check"><input id="cuPublished" type="checkbox" ${c.published!==false?'checked':''}> Publish on website</label></div>`,`<button class="btn btn-primary" onclick="saveCustomer('${id||''}')">Save Customer</button>`); $('#cuImage').addEventListener('change',()=>previewFile($('#cuImage'),$('#cuPreview'))); }
async function saveCustomer(id){try{let image=null;if($('#cuImage').files[0])image=await fileToData($('#cuImage'));const c={name:$('#cuName').value.trim(),tagline:$('#cuTagline').value.trim(),website:$('#cuWebsite').value.trim(),published:$('#cuPublished').checked};if(!c.name)throw new Error('Customer/company name is required.');if(image){c.imageData=image.dataUrl;c.imageName=image.name;}await saveCollection('customers',id,c);closeGeneric();toast(id?'Customer updated successfully.':'Customer added successfully.');}catch(e){toast(e.message,true)}}

function openReviewForm(id){const r=id?DATA.reviews.find(x=>x.id===id):{name:'',rating:5,text:'',source:'Manual',published:true,featured:false,date:new Date().toISOString().slice(0,10)}; modal(`${id?'Edit':'Add'} Review`,`<div class="form-grid"><div class="field"><label>Customer Name</label><input id="rName" value="${esc(r.name)}"></div><div class="field"><label>Rating</label><select id="rRating">${[5,4,3,2,1].map(x=>`<option ${Number(r.rating)===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Source</label><select id="rSource">${['Manual','Google','WhatsApp','Instagram','Other'].map(x=>`<option ${x===r.source?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Date</label><input id="rDate" type="date" value="${esc(r.date||'')}"></div><div class="field span-2"><label>Review text</label><textarea id="rText">${esc(r.text)}</textarea></div><div class="field span-2"><label>Customer photo (optional)</label><input id="rImage" type="file" accept="image/*"><div id="rPreview" class="upload-preview">${r.image?`<img src="${esc(r.image)}" alt="">`:'No photo selected'}</div></div><label class="check"><input id="rPublished" type="checkbox" ${r.published?'checked':''}> Publish</label><label class="check"><input id="rFeatured" type="checkbox" ${r.featured?'checked':''}> Feature</label></div>`,`<button class="btn btn-primary" onclick="saveReview('${id||''}')">Save Review</button>`); $('#rImage').addEventListener('change',()=>previewFile($('#rImage'),$('#rPreview'))); }
async function saveReview(id){try{let image=null;if($('#rImage').files[0])image=await fileToData($('#rImage'));const r={name:$('#rName').value.trim(),rating:Number($('#rRating').value),text:$('#rText').value.trim(),source:$('#rSource').value,published:$('#rPublished').checked,featured:$('#rFeatured').checked,date:$('#rDate').value||new Date().toISOString().slice(0,10)};if(!r.name||!r.text)throw new Error('Customer name and review text are required.');if(image){r.imageData=image.dataUrl;r.imageName=image.name;}await saveCollection('reviews',id,r);closeGeneric();toast(id?'Review updated successfully.':'Review added successfully.');}catch(e){toast(e.message,true)}}

function editGallery(id){const g=DATA.gallery.find(x=>x.id===id);if(!g)return; modal('Edit Gallery Photo',`<div class="field"><label>Caption / Alt text</label><input id="gAlt" value="${esc(g.alt||'')}"></div><div class="field" style="margin-top:13px"><label>Replace image (optional)</label><input id="gImage" type="file" accept="image/*"><div id="gPreview" class="upload-preview"><img src="${esc(g.image)}" alt=""></div></div><label class="check" style="margin-top:12px"><input id="gPublished" type="checkbox" ${g.published!==false?'checked':''}> Published</label>`,`<button class="btn btn-primary" onclick="saveGallery('${g.id}')">Save Photo</button>`); $('#gImage').addEventListener('change',()=>previewFile($('#gImage'),$('#gPreview'))); }
async function uploadGallery(input){ const files=[...input.files]; if(!files.length)return; try{ for(const file of files){ if(file.size>8*1024*1024)throw new Error(`${file.name} is larger than 8 MB.`); const data=await fileToDataFromFile(file); await api('/api/gallery',{method:'POST',body:JSON.stringify({alt:file.name.replace(/\.[^.]+$/,''),published:true,imageData:data.dataUrl,imageName:file.name})}); } input.value=''; await refreshData(); toast(`${files.length} gallery photo(s) uploaded successfully.`);}catch(e){toast(e.message,true);} }
async function saveGallery(id){try{const g={alt:$('#gAlt').value.trim(),published:$('#gPublished').checked};if($('#gImage').files[0]){const f=await fileToData($('#gImage'));g.imageData=f.dataUrl;g.imageName=f.name;}await saveCollection('gallery',id,g);closeGeneric();toast('Gallery photo updated successfully.');}catch(e){toast(e.message,true)}}

function openFaqForm(id){const f=id?DATA.faqs.find(x=>x.id===id):{q:'',a:'',published:true}; modal(`${id?'Edit':'Add'} FAQ`,`<div class="field"><label>Question</label><input id="fq" value="${esc(f.q)}"></div><div class="field" style="margin-top:13px"><label>Answer</label><textarea id="fa">${esc(f.a)}</textarea></div><label class="check" style="margin-top:13px"><input id="fp" type="checkbox" ${f.published!==false?'checked':''}> Published</label>`,`<button class="btn btn-primary" onclick="saveFaq('${id||''}')">Save FAQ</button>`);}
async function saveFaq(id){try{const p={q:$('#fq').value.trim(),a:$('#fa').value.trim(),published:$('#fp').checked};if(!p.q||!p.a)throw new Error('Question and answer are required.');await saveCollection('faqs',id,p);closeGeneric();toast('FAQ saved successfully.');}catch(e){toast(e.message,true)}}
function openOfferForm(id){const o=id?DATA.offers.find(x=>x.id===id):{title:'',description:'',discount:'',startDate:'',endDate:'',active:true}; modal(`${id?'Edit':'Add'} Offer`,`<div class="form-grid"><div class="field"><label>Offer title</label><input id="oTitle" value="${esc(o.title)}"></div><div class="field"><label>Discount</label><input id="oDiscount" value="${esc(o.discount||'')}"></div><div class="field span-2"><label>Description</label><textarea id="oDesc">${esc(o.description||'')}</textarea></div><div class="field"><label>Start date</label><input id="oStart" type="date" value="${esc(o.startDate||'')}"></div><div class="field"><label>End date</label><input id="oEnd" type="date" value="${esc(o.endDate||'')}"></div><label class="check"><input id="oActive" type="checkbox" ${o.active!==false?'checked':''}> Active</label></div>`,`<button class="btn btn-primary" onclick="saveOffer('${id||''}')">Save Offer</button>`);}
async function saveOffer(id){try{const p={title:$('#oTitle').value.trim(),description:$('#oDesc').value.trim(),discount:$('#oDiscount').value.trim(),startDate:$('#oStart').value,endDate:$('#oEnd').value,active:$('#oActive').checked};if(!p.title)throw new Error('Offer title is required.');if(p.startDate&&p.endDate&&p.endDate<p.startDate)throw new Error('End date cannot be before start date.');await saveCollection('offers',id,p);closeGeneric();toast('Offer saved successfully.');}catch(e){toast(e.message,true)}}

async function saveContent(){try{const parseLines=s=>String(s||'').split(/\n+/).map(line=>line.trim()).filter(Boolean).map(line=>{const i=line.indexOf('||');return {title:(i>=0?line.slice(0,i):line).trim(),text:(i>=0?line.slice(i+2):'').trim()}}).filter(x=>x.title&&x.text);const p={heroBadge:$('#cHeroBadge').value.trim(),heroHeading:$('#cHeroHeading').value.trim(),heroText:$('#cHeroText').value.trim(),whyTitle:$('#cWhyTitle').value.trim(),whyText:$('#cWhyText').value.trim(),whyPoints:parseLines($('#cWhyPoints').value),hygieneTitle:$('#cHygieneTitle').value.trim(),hygieneText:$('#cHygieneText').value.trim(),hygienePoints:parseLines($('#cHygienePoints').value),hygieneNote:$('#cHygieneNote').value.trim(),aboutTitle:$('#cAboutTitle').value.trim(),aboutText:$('#cAboutText').value.trim(),finalTitle:$('#cFinalTitle').value.trim(),finalText:$('#cFinalText').value.trim()};if(!p.heroHeading)throw new Error('Hero heading is required.');await api('/api/site-content',{method:'PUT',body:JSON.stringify(p)});await refreshData();toast('Homepage content saved successfully.');}catch(e){toast(e.message,true)}}
async function saveSettings(){try{const p={brand:$('#sBrand').value.trim(),tagline:$('#sTagline').value.trim(),whatsapp:$('#sWhatsApp').value.replace(/\D/g,''),shipping:Number($('#sShipping').value)||0,instagram:$('#sInstagram').value.trim(),facebook:$('#sFacebook').value.trim(),email:$('#sEmail').value.trim(),address:$('#sAddress').value.trim(),payment:$('#sPayment').value.trim(),cod:$('#sCod').value==='true',established:$('#sEstablished').value.trim()};if(p.whatsapp.length<10)throw new Error('Please enter a valid WhatsApp number with country code.');await api('/api/settings',{method:'PUT',body:JSON.stringify(p)});await refreshData();toast('Business settings saved successfully.');}catch(e){toast(e.message,true)}}
async function saveGoogleSettings(){try{const p={googlePlaceId:$('#sGooglePlaceId').value.trim(),googleReviewsEnabled:$('#sGoogleEnabled').checked};await api('/api/settings',{method:'PUT',body:JSON.stringify(p)});await refreshData();toast('Google review settings saved successfully.');}catch(e){toast(e.message,true)}}
async function saveStats(){try{const p={towelsSold:Math.max(0,Number($('#stTowels').value)||0),designsMade:Math.max(0,Number($('#stDesigns').value)||0)};await api('/api/stats',{method:'PUT',body:JSON.stringify(p)});await refreshData();toast('Business counts saved successfully.');}catch(e){toast(e.message,true)}}

async function saveCollection(type,id,payload){ await api(id?`/api/${type}/${id}`:`/api/${type}`,{method:id?'PUT':'POST',body:JSON.stringify(payload)}); await refreshData(); }
async function togglePublish(type,id){ try{const item=DATA[type].find(x=>x.id===id);if(!item)return;await api(`/api/${type}/${id}`,{method:'PUT',body:JSON.stringify({published:item.published===false})});await refreshData();toast(item.published===false?'Published successfully.':'Hidden from website.');}catch(e){toast(e.message,true)}}
async function toggleReview(id){try{const r=DATA.reviews.find(x=>x.id===id);if(!r)return;await api(`/api/reviews/${id}`,{method:'PUT',body:JSON.stringify({published:!r.published})});await refreshData();toast(r.published?'Review hidden from website.':'Review published on website.');}catch(e){toast(e.message,true)}}
async function featureReview(id){try{const r=DATA.reviews.find(x=>x.id===id);if(!r)return;await api(`/api/reviews/${id}`,{method:'PUT',body:JSON.stringify({featured:!r.featured})});await refreshData();toast(r.featured?'Review removed from featured.':'Review added to featured.');}catch(e){toast(e.message,true)}}
async function toggleOffer(id){try{const o=DATA.offers.find(x=>x.id===id);if(!o)return;await api(`/api/offers/${id}`,{method:'PUT',body:JSON.stringify({active:!o.active})});await refreshData();toast(o.active?'Offer disabled.':'Offer enabled.');}catch(e){toast(e.message,true)}}
async function deleteItem(type,id){ const item=(DATA[type]||[]).find(x=>x.id===id); if(!item)return; if(!confirm(`Delete this ${type.slice(0,-1)}? This will remove it from the website.`))return; try{const d=await api(`/api/${type}/${id}`,{method:'DELETE'});await refreshData();toast(d.message||'Item deleted successfully.');}catch(e){toast(e.message,true)} }

async function setEnquiryStatus(id,status){try{await api(`/api/enquiries/${id}`,{method:'PUT',body:JSON.stringify({status})});await refreshData();toast(`Enquiry marked ${status}.`);}catch(e){toast(e.message,true)}}

async function fileToData(input){return fileToDataFromFile(input.files[0]);}
function fileToDataFromFile(file){return new Promise((resolve,reject)=>{if(!file)return reject(new Error('Please choose a file.'));reader({files:[file]},()=>{});const r=new FileReader();r.onload=()=>resolve({dataUrl:r.result,name:file.name,size:file.size});r.onerror=()=>reject(new Error('Could not read the selected file.'));r.readAsDataURL(file);});}

async function importGoogleReviews(input){try{const file=input.files[0];if(!file)return;const json=JSON.parse(await file.text());const reviews=Array.isArray(json)?json:json.reviews;if(!Array.isArray(reviews)||!reviews.length)throw new Error('JSON must contain a non-empty reviews array.');const d=await api('/api/google-reviews/import',{method:'POST',body:JSON.stringify({reviews})});input.value='';await refreshData();toast(d.message||'Google review data imported successfully.');}catch(e){input.value='';toast(e.message,true)}}
async function testGoogleReviews(){try{const status=await api('/api/google-reviews/status');const box=$('#googleStatusResult');const parts=[status.message,`API key: ${status.apiKeyConfigured?'configured':'missing'}`,`Place ID: ${status.placeIdConfigured?'configured':'missing'}`,`Public display: ${status.enabled?'enabled':'disabled'}`];if(box)box.innerHTML=`<div class="${status.configured?'health-ok':'health-warn'}">${status.configured?'✓':'!'} ${esc(parts.join(' • '))}</div>`;if(!status.configured){modal('Google Reviews Setup',`<div class="notice"><strong>${esc(status.message)}</strong></div><div class="setup-steps"><div><b>1.</b> Put your Google Places API key in <code>.env</code> as <code>GOOGLE_PLACES_API_KEY=...</code>.</div><div><b>2.</b> Enter the Google Place ID in Admin → Settings.</div><div><b>3.</b> Enable live reviews and save.</div><div><b>4.</b> Click Check Connection again.</div></div>`,'');return;}const live=await api('/api/google-reviews/test');if(box)box.innerHTML=`<div class="health-ok">✓ Connected to <strong>${esc(live.placeName||'Google Business listing')}</strong>. Rating: ${live.rating??'—'} from ${live.userRatingCount??'—'} ratings. ${live.reviews.length} review(s) returned.</div>`;toast('Google Reviews connection check passed.');}catch(e){const box=$('#googleStatusResult');if(box)box.innerHTML=`<div class="health-error">✕ ${esc(e.message)}</div>`;toast(e.message,true)}}
function openGoogleSettings(){showSection('settings');setTimeout(testGoogleReviews,150);}

async function downloadBackup(){try{const data=await api('/api/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`mazatowel-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup downloaded successfully.');}catch(e){toast(e.message,true)}}
async function importBackupFile(input){try{const data=JSON.parse(await input.files[0].text());if(!data.products||!data.designs)throw new Error('Invalid backup file.');if(!confirm('Import this backup and replace current website data?'))return;const d=await api('/api/import',{method:'POST',body:JSON.stringify(data)});input.value='';await refreshData();toast(d.message||'Backup imported successfully.');}catch(e){input.value='';toast(e.message,true)}}
function quickAdd(){modal('Quick Add','<div class="quick-grid"><button class="btn btn-primary" onclick="closeGeneric();openProductForm()">+ Add Product</button><button class="btn btn-gold" onclick="closeGeneric();openDesignForm()">+ Add Design</button><button class="btn btn-secondary" onclick="closeGeneric();showSection(\'gallery\')">+ Upload Photos</button><button class="btn btn-secondary" onclick="closeGeneric();openCustomerForm()">+ Add Customer</button><button class="btn btn-secondary" onclick="closeGeneric();openReviewForm()">+ Add Review</button><button class="btn btn-secondary" onclick="closeGeneric();showSection(\'enquiries\')">View Enquiries</button></div>','');}
async function logout(){try{await api('/api/logout',{method:'POST'});}catch{}location.reload();}

function loginScreen(message=''){ $('#adminApp').innerHTML=`<div class="login"><div class="login-card"><div class="brand"><img class="brand-logo" src="/assets/mazatowel-logo-tight.png" alt="MazaTowel logo"></div><div class="login-kicker">Private Admin Panel</div><h1>Welcome back</h1><p class="muted">Manage MazaTowel products, designs, customer logos, reviews and website content.</p>${message?`<div class="health-error" style="margin-top:14px">${esc(message)}</div>`:''}<div class="field" style="margin-top:18px"><label>Email</label><input id="loginEmail" value="admin@mazatowel.in" autocomplete="username"></div><div class="field" style="margin-top:13px"><label>Password</label><div class="password-field-wrap"><input id="loginPassword" type="password" autocomplete="current-password" placeholder="Enter password"><button type="button" class="toggle-password-btn" onclick="toggleAdminPassword()" aria-label="Toggle password visibility" title="Show/Hide password"><svg id="pwEyeIcon" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div><div id="loginError" class="form-error"></div><button class="btn btn-primary" style="width:100%;margin-top:12px;padding:13px" onclick="doLogin()">Sign in</button><div class="notice" style="margin-top:14px">Demo default: <code>MazaTowel123!</code>. For production, set <code>ADMIN_EMAIL</code> and <code>ADMIN_PASSWORD</code> in <code>.env</code>.</div></div></div>`; }
function toggleAdminPassword(){const input=$('#loginPassword');if(!input)return;const isPw=input.type==='password';input.type=isPw?'text':'password';const icon=$('#pwEyeIcon');if(icon){icon.innerHTML=isPw?'<path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/>':'<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>';}}
async function doLogin(){try{await api('/api/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value})});await load();toast('Signed in successfully.');}catch(e){$('#loginError').textContent=e.message;}}
async function boot(){try{const status=await api('/api/auth/status');if(!status.authenticated){loginScreen();return;}await load();}catch(e){loginScreen(e.message);}}
boot();
